#[cfg(test)]
mod burst_reproduction {
    use super::*;
    use tokio::io::{AsyncReadExt, AsyncWriteExt};

    #[tokio::test]
    async fn queued_during_read_ack_starts_without_timer_delay() {
        let dir = std::env::temp_dir().join(format!("ting-burst-{}", uuid::Uuid::new_v4()));
        private_dir(&dir).unwrap();
        let profile = Profile { dir: dir.clone() };
        profile.save("settings.json", &Settings { telemetry: Some(false), ..Settings::default() }).unwrap();
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let api = format!("http://{}", listener.local_addr().unwrap());
        let (callbacks, mut arrivals) = mpsc::channel(2);
        let server = tokio::spawn(async move {
            for expected in ["first", "second"] {
                let (mut socket, _) = listener.accept().await.unwrap();
                let mut bytes = Vec::new();
                let header_end = loop {
                    let mut chunk = [0u8; 1024];
                    let size = socket.read(&mut chunk).await.unwrap();
                    assert!(size > 0);
                    bytes.extend_from_slice(&chunk[..size]);
                    if let Some(end) = bytes.windows(4).position(|s| s == b"\r\n\r\n") { break end+4; }
                };
                let headers = String::from_utf8(bytes[..header_end].to_vec()).unwrap();
                assert!(headers.starts_with("POST /hook "));
                let length = headers.lines().find_map(|l| l.to_ascii_lowercase().strip_prefix("content-length:").map(|v| v.trim().parse::<usize>().unwrap())).unwrap();
                while bytes.len() < header_end+length {
                    let mut chunk=[0u8;1024];
                    let size=socket.read(&mut chunk).await.unwrap();
                    assert!(size>0);
                    bytes.extend_from_slice(&chunk[..size]);
                }
                let value: Value = serde_json::from_slice(&bytes[header_end..header_end+length]).unwrap();
                assert_eq!(value["tings"][0]["id"], expected);
                callbacks.send(std::time::Instant::now()).await.unwrap();
                socket.write_all(b"HTTP/1.1 204 No Content\r\nContent-Length: 0\r\nConnection: close\r\n\r\n").await.unwrap();
            }
        });
        let store=Arc::new(Store::open(&dir.join("queue.sqlite")).unwrap());
        store.db.lock().unwrap().execute("INSERT INTO hooks(id,profile,api,org,token_hash,url) VALUES(?1,?2,?3,'tos','unused',?4)",params!["hook",dir.to_str().unwrap(),api,format!("{api}/hook")]).unwrap();
        let queue=|id:&str| {
            store.queue(&json!({"org_id":"tos","webhook_id":"hook","tings":[{"id":id,"created_at":Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis,true),"type":"tos>dm.msg.received","for":"si_test","key":id,"data":{},"metadata":{}}]}),&api).unwrap();
        };
        let (tx, mut commands)=mpsc::channel::<SocketCommand>(2);
        let shared=Shared {
            store:store.clone(),tx,
            socket:Arc::new(RwLock::new(SocketStatus { authorized:HashSet::from(["hook".into()]),..SocketStatus::default() })),
            wake:Arc::new(Notify::new()),
            leases:Arc::new(Mutex::new((None,0))),
        };
        queue("first");
        let worker=tokio::spawn(workers(shared.clone()));
        tokio::time::timeout(Duration::from_secs(2),arrivals.recv()).await.unwrap().unwrap();
        let first_ack=tokio::time::timeout(Duration::from_secs(2),commands.recv()).await.unwrap().unwrap();
        assert_eq!(first_ack.body["message_ids"],json!(["first"]));
        queue("second");
        shared.wake.notify_one();
        // Let workers consume this wake while the first job is awaiting its ACK.
        tokio::time::sleep(Duration::from_millis(50)).await;
        let released=std::time::Instant::now();
        first_ack.reply.send(Ok(json!({"op":"acked"}))).unwrap();
        let second=tokio::time::timeout(Duration::from_secs(2),arrivals.recv()).await.unwrap().unwrap();
        let elapsed=second.duration_since(released);
        let second_ack=tokio::time::timeout(Duration::from_secs(2),commands.recv()).await.unwrap().unwrap();
        second_ack.reply.send(Ok(json!({"op":"acked"}))).unwrap();
        server.await.unwrap();
        worker.abort();
        let _=worker.await;
        drop(shared); drop(store);
        fs::remove_dir_all(dir).unwrap();
        eprintln!("SECOND_CALLBACK_AFTER_ACK_RELEASE_MS={:.3}",elapsed.as_secs_f64()*1000.0);
        assert!(elapsed < Duration::from_millis(500), "already queued second callback waited for worker timer: {elapsed:?}");
    }
}

